async createBugsFromFailures(
  failures: TestFailure[],
  options: { userStoryId?: string; dryRun?: boolean; updateExisting?: boolean } = {}
): Promise<AgentResponse> {
  const results: CreatedBug[] = [];

  for (const failure of failures) {
    // Dedup gate first — never file blind. One WIQL round-trip per failure.
    const existingBug = await this.findExistingBug(failure);

    if (existingBug) {
      // Known failure: append a recurrence comment, or skip entirely.
      if (options.updateExisting) {
        await this.updateBug(existingBug.id, failure);
        results.push({ ...existingBug, action: 'updated' });
      } else {
        results.push({ ...existingBug, action: 'skipped-existing' });
      }
      continue; // never fall through to create
    }

    // New failure. dryRun runs the full decide path but suppresses the POST,
    // so you can preview exactly what would be filed with zero side effects.
    if (!options.dryRun) {
      const bug = await this.createBug(failure, options.userStoryId);
      results.push(bug);
    }
  }
  // ...tally created / updated / skipped for the AgentResponse summary
  return { success: true, bugs: results } as AgentResponse;
}

private async findExistingBug(failure: TestFailure) {
  // Dedup key = test case + browser. Both must be in the title so the same
  // test failing on Chrome vs Firefox stays two separate bugs (distinct repros).
  const wiql = `
    SELECT [System.Id], [System.Title], [System.State]
    FROM WorkItems
    WHERE [System.WorkItemType] = 'Bug'
      AND [System.State] <> 'Closed'      -- ignore already-fixed bugs, so a
      AND [System.State] <> 'Resolved'    -- regression opens a fresh ticket
      AND [System.Title] CONTAINS '${failure.testCase}'
      AND [System.Title] CONTAINS '${failure.browser}'
  `;

  // WIQL is POST-only and returns work-item IDs, never fields.
  const response = await fetch(`${this.baseUrl}/wit/wiql?api-version=7.0`, {
    method: 'POST',
    headers: { Authorization: this.authHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({ query: wiql }),
  });

  const result = await response.json();
  if (result.workItems?.length > 0) {
    // Hit → hydrate the first match (getBug = GET /wit/workitems/{id}) so the
    // caller gets a usable { id, url, title } instead of a bare id.
    const bugId = result.workItems[0].id;
    const bugDetails = await this.getBug(bugId);
    return { id: bugId, url: bugDetails._links.html.href, title: bugDetails.fields['System.Title'] };
  }
  return null; // Miss → caller proceeds to createBug.
}

private determineSeverity(failure: TestFailure): BugDetails['severity'] {
  const testCase = failure.testCase.toLowerCase();
  const error = failure.error.toLowerCase();

  // Tiers are checked top-down; the FIRST match wins, so order = precedence.

  // Critical: smoke or explicitly-critical tests — these gate the whole suite.
  if (testCase.includes('critical') || testCase.includes('smoke')) {
    return '1 - Critical';
  }

  // High: auth/navigation core paths, or any timeout (usually a real hang).
  if (
    testCase.includes('navigate') ||
    testCase.includes('login') ||
    testCase.includes('auth') ||
    error.includes('timeout')
  ) {
    return '2 - High';
  }

  // Medium: regression coverage — important, not blocking.
  if (testCase.includes('regression')) {
    return '3 - Medium';
  }

  // Low: everything else (UI validation, formatting, cosmetic).
  return '4 - Low';
}

private buildBugDetails(failure: TestFailure, parentStoryId?: string): BugDetails {
  // Grades computed up front so the payload is fully deterministic.
  const severity = this.determineSeverity(failure);
  const priority = this.determinePriority(failure);

  return {
    // Title IS the dedup key (see findExistingBug) — keep this template stable.
    title: `[Automation] ${failure.testCase} failed on ${failure.browser}`,
    description: this.formatDescription(failure),   // HTML, human-readable
    reproSteps: this.formatReproSteps(failure),     // HTML, numbered steps
    severity,
    priority,
    // areaPath routes the bug to a team's backlog; env override → project default.
    areaPath: process.env.ADO_AREA_PATH || `${this.project}\\MyTeam`,
    iterationPath: process.env.ADO_ITERATION_PATH,  // optional sprint assignment
    tags: this.buildTags(failure),
  };
}

private async createBug(failure: TestFailure, parentStoryId?: string): Promise<CreatedBug> {
  const bugDetails = this.buildBugDetails(failure, parentStoryId);

  // ADO create = JSON-Patch: an array of add-ops, one per field.
  const patchDocument = [
    { op: 'add', path: '/fields/System.Title', value: bugDetails.title },
    { op: 'add', path: '/fields/System.Description', value: bugDetails.description },
    { op: 'add', path: '/fields/Microsoft.VSTS.TCM.ReproSteps', value: bugDetails.reproSteps },
    { op: 'add', path: '/fields/Microsoft.VSTS.Common.Severity', value: bugDetails.severity },
    { op: 'add', path: '/fields/Microsoft.VSTS.Common.Priority', value: bugDetails.priority },
    { op: 'add', path: '/fields/System.Tags', value: bugDetails.tags?.join('; ') || '' },
  ];

  // Note the content-type (json-patch+json) and the $Bug work-item-type in the path.
  const response = await fetch(`${this.baseUrl}/wit/workitems/$Bug?api-version=7.0`, {
    method: 'POST',
    headers: { Authorization: this.authHeader, 'Content-Type': 'application/json-patch+json' },
    body: JSON.stringify(patchDocument),
  });

  const bug = await response.json();

  // Two best-effort follow-ups, only after the bug exists:
  if (parentStoryId || failure.userStoryId) {
    await this.linkToUserStory(bug.id, parentStoryId || failure.userStoryId!); // parent link
  }
  if (failure.screenshot) {
    await this.addAttachment(bug.id, failure.screenshot, 'screenshot.png');    // attach evidence
  }

  return { id: bug.id, url: bug._links.html.href, title: bugDetails.title, action: 'created' };
}

private async updateBug(bugId: number, failure: TestFailure): Promise<void> {
  // Recurrence note, not a new bug: append an HTML comment to the existing one
  // so every repeat of this failure stays on a single work item.
  const comment = `
<h3>Test Failed Again</h3>
<p><strong>Timestamp:</strong> ${new Date().toISOString()}</p>
<p><strong>Browser:</strong> ${failure.browser}</p>
<p><strong>Error:</strong></p>
<pre>${this.escapeHtml(failure.error)}</pre>
  `; // error is escaped — failure text is untrusted and often contains < >

  // comments is a -preview endpoint, so the api-version is pinned to it.
  await fetch(`${this.baseUrl}/wit/workitems/${bugId}/comments?api-version=7.0-preview`, {
    method: 'POST',
    headers: { Authorization: this.authHeader, 'Content-Type': 'application/json' },
    body: JSON.stringify({ text: comment }),
  });
}
